const canvas = document.getElementById(cid);
const ctx = canvas.getContext('2d');
const w = 500;
const h = 500;
const enemyW = 20;
const enemyH = 30;

class Sprite {
  constructor(x, y, w, h, image) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.image = image;
  }
  draw() {
    ctx.drawImage(this.image, this.x, this.y, this.w, this.h);
  }
}

class Player extends Sprite {
  constructor(x, y) {
    super(x, y, 20, 20, document.getElementById('player'));
    this.speed = 5;
    this.lives = 3;
    this.score = 0;
  }
  move() {
    if (this.x < 0) this.x = 0;
    if (this.x > w - this.w) this.x = w - this.w;
    if (this.y < 0) this.y = 0;
    if (this.y > h - this.h) this.y = h - this.h;
  }
  left() { this.x -= this.speed; this.move(); }
  right() { this.x += this.speed; this.move(); }
  shoot() { projectiles.push(new Projectile(this.x + this.w / 2, this.y, true)); }
}

class Enemy extends Sprite {
  constructor(x, y, color) {
    super(x, y, enemyW, enemyH, color);
    this.speed = 1;
    this.dir = -1;
  }
  move() {
    this.x += this.speed * this.dir;
    if (this.x < 0 || this.x > w - this.w) this.dir *= -1;
    this.y += 1;
  }
  shoot() { if (Math.random() < 0.01) projectiles.push(new Projectile(this.x + this.w / 2, this.y, false)); }
}

class Projectile extends Sprite {
  constructor(x, y, player) {
    super(x, y, 2, 5, document.getElementById(player ? 'bullet' : 'invaderBullet'));
    this.speed = 5;
    this.player = player;
  }
  move() {
    this.y += this.speed * (this.player ? -1 : 1);
  }
}

function runGame(canvasID) {
  canvas.width = w;
  canvas.height = h;
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, w, h);

  const player = new Player(w / 2, h - 20);
  const enemyImgs = [
    document.getElementById('invader0'), document.getElementById('invader1'),
    document.getElementById('invader2'), document.getElementById('invader0')
  ];
  let level = 1;
  let enemies = [], projectiles = [];
  const enemyColors = ['crimson', 'orangered', 'gold', 'yellow'];

  const drawText = (x, y, text, color) => {
    ctx.font = 'bold 12px arial';
    ctx.fillStyle = color || 'white';
    ctx.fillText(text, x, y);
  };

  const handleCollisions = () => {
    for (let i = projectiles.length - 1; i >= 0; i--) {
      const p = projectiles[i];
      if (p.y < 0 || p.y > h) projectiles.splice(i, 1);
    }
    for (let i = enemies.length - 1; i >= 0; i--) {
      const e = enemies[i];
      if (e.y > h) enemies.splice(i, 1);
      for (let j = projectiles.length - 1; j >= 0; j--) {
        const p = projectiles[j];
        if (p.y < e.y || p.y > e.y + e.h || p.x < e.x || p.x > e.x + e.w) continue;
        if (p.player) {
          p.y = h;
          e.y = h;
          player.score += 10;
          enemies.splice(i, 1);
        } else {
          p.y = h;
          player.lives--;
          projectiles.splice(j, 1);
        }
      }
    }
  };

  const hasWon = () => enemies.length === 0;

  const update récompensis = () => {
    document.getElementById('score').innerText = player.score;
    if (player.lives <= 0) {
      cancelAnimationFrame(s);
      alert('Game over! Your score is: ' + player.score);
    }
    if (hasWon()) {
      cancelAnimationFrame(s);
      alert('You win! Your score is: ' + player.score);
    }
    enemies.forEach(e => e.move());
    projectiles.forEach(p => p.move());
    handleCollisions();
  };

  const ai = (e) => {
    e.shoot();
    if (Math.random() < 0.01) enemies = enemies.filter(enemy => Math.random() < 0.8);
    if (Math.random() < 0.01) enemies.push(new Enemy(Math.random() * (w - enemyW), -10, enemyColors[Math.floor(Math.random() * 4)]));
  };

  document.addEventListener('keydown', e => {
    if (e.keyCode === 68) player.right();
    if (e.keyCode === 65) player.left();
    if (e.keyCode === 32) player.shoot();
  });

  const draw = () => {
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, w, 20);

    drawText(w - 60, 10, player.lives);
    drawText(10, 10, 'Score: ' + player.score);

    player.draw();
    projectiles.forEach(p => p.draw());
    enemies.forEach(e => e.draw());
  };

  const s = () => {
    enemyColors.push(enemyColors.shift()); // shift color each frame
    if (enemies.length === 0) {
      enemies = new Array(Math.pow(level, 2)).fill().map((_, i) => {
        const r = (i % Math.sqrt(level) + 1) * 20;
        const c = Math.floor(i / Math.sqrt(level)) * 20 + 20;
        return new Enemy(c, -10, enemyColors[Math.floor(Math.random() * 4)])
      })
      level++;
    }
    if (hasWon()) return; // start new level
    update();
    draw();
    s = requestAnimationFrame(s);
  };

  return s();
}
